function sumOfDigits(nums) {
  let rest = Math.min(...nums);
  let digitSum = 0;

  while (rest > 0) {
    digitSum += rest % 10;
    rest = Math.floor(rest / 10);
  }
  return digitSum % 2 === 0 ? 1 : 0;
}

