function sumOfDigits(nums) {
  // Sort a copy, read the first value as text and add its characters.
  const smallest = [...nums].sort((a, b) => a - b)[0];
  const total = String(smallest).split('').reduce((acc, ch) => acc + Number(ch), 0);
  return total % 2 === 1 ? 0 : 1;
}

