function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(1, 6);
  const low = size === 'large' ? int(1, 60) : int(1, 100);
  return [Array.from({ length: n }, () => int(low, 100))];
}
